#include "test_common.h"
#include "blood_inventory.h"
static uint32_t low_count=0;static BmsStatus_t low_visit(const BmsBloodInventory_t*r,void*c){(void)r;(*(uint32_t*)c)++;return BMS_STATUS_OK;}
static void test_inventory_stock(void){BmsInventoryContext_t c;BmsBloodInventory_t r={1U,BMS_BLOOD_GROUP_A_POSITIVE,5U,{2026,1,1},{2026,12,31},true},out;uint32_t units=0;ASSERT_STATUS(BMS_STATUS_OK,BloodInventoryInitialize(&c));ASSERT_STATUS(BMS_STATUS_OK,BloodInventoryAddStock(&c,&r));ASSERT_STATUS(BMS_STATUS_OK,BloodInventorySearchById(&c,1U,&out));ASSERT_STATUS(BMS_STATUS_OK,BloodInventoryGetAvailableUnits(&c,BMS_BLOOD_GROUP_A_POSITIVE,&units));CU_ASSERT_EQUAL(units,5U);ASSERT_STATUS(BMS_STATUS_OK,BloodInventoryRemoveStock(&c,1U,2U));ASSERT_STATUS(BMS_STATUS_INSUFFICIENT_STOCK,BloodInventoryRemoveStock(&c,1U,10U));low_count=0;ASSERT_STATUS(BMS_STATUS_OK,BloodInventoryDetectLowStock(&c,5U,low_visit,&low_count));CU_ASSERT_EQUAL(low_count,1U);BloodInventoryDeinitialize(&c);}
static void test_expiry(void){BmsInventoryContext_t c;BmsBloodInventory_t r={2U,BMS_BLOOD_GROUP_O_NEGATIVE,1U,{2024,1,1},{2024,2,1},true};BmsDate_t now={2026,1,1};uint32_t removed=0;BloodInventoryInitialize(&c);BloodInventoryAddStock(&c,&r);ASSERT_STATUS(BMS_STATUS_OK,BloodInventoryRemoveExpired(&c,&now,&removed));CU_ASSERT_EQUAL(removed,1U);BloodInventoryDeinitialize(&c);}
void RegisterInventoryTests(void){CU_pSuite s=CU_add_suite("Inventory",NULL,NULL);CU_add_test(s,"stock operations",test_inventory_stock);CU_add_test(s,"expiry",test_expiry);}
